import { Component } from '@angular/core';
import { RadioGroupComponent } from '@conciso/design-system-angular';

@Component({
  selector: 'app-demo',
  imports: [RadioGroupComponent],
  template: `
    <cds-radio-group
        [legend]="'Bevorzugter Kontaktweg'"
        [options]="['E-Mail', 'Telefon', 'Beides']"
        [value]="'E-Mail'"
        [required]="false"
        [disabled]="false"
        [area]="'co'"
        (disabledChange)="disabledChange($event)"
        (valueChange)="valueChange($event)"
    />`,
})
export class DemoComponent {
  disabledChange(event: unknown) {}
  valueChange(event: unknown) {}
}

