komponenten-inputs-forms-radio--formular.snippet:
import { Component } from '@angular/core';
import { RadioGroupComponent } from '@conciso/design-system-angular';

@Component({
  selector: 'app-demo',
  imports: [RadioGroupComponent],
  template: `
    <div style="display:flex;flex-direction:column;gap:var(--s3);max-width:28rem">
        <cds-radio-group
            legend="Bevorzugter Kontaktweg"
            [options]="options"
            [formControl]="ctrl">
        </cds-radio-group>
        <p style="font:14px/1.4 system-ui,sans-serif;margin:0">
            Wert:
            <strong>{{ ctrl.value || '(leer)' }}</strong>
        </p>
    </div>`,
})
export class DemoComponent {
  options = ['E-Mail', 'Telefon', 'Beides'];
}
